solutionSql:
SELECT name, dept_id,
       DENSE_RANK() OVER (PARTITION BY dept_id ORDER BY salary DESC) AS rnk
FROM employees;

SELECT name,
       ROUND(100.0 * salary / SUM(salary) OVER (PARTITION BY dept_id), 2) AS pct_of_payroll
FROM employees;

SELECT name, salary,
       LAG(salary) OVER (ORDER BY salary DESC, id) - salary AS gap
FROM employees;

SELECT hire_date, name,
       COUNT(*) OVER (ORDER BY hire_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS headcount
FROM employees;

SELECT dept_id, name, hire_date
FROM (
  SELECT *, RANK() OVER (PARTITION BY dept_id ORDER BY hire_date) AS rnk
  FROM employees
)
WHERE rnk = 1;

SELECT strftime('%Y', hire_date) AS year, COUNT(*) AS hires
FROM employees
GROUP BY year;

SELECT AVG(salary) AS median_salary FROM (
  SELECT salary FROM employees WHERE salary IS NOT NULL
  ORDER BY salary
  LIMIT 2 - (SELECT COUNT(*) FROM employees WHERE salary IS NOT NULL) % 2
  OFFSET (SELECT (COUNT(*) - 1) / 2 FROM employees WHERE salary IS NOT NULL)
);

SELECT name,
       ROUND(salary - AVG(salary) OVER (PARTITION BY dept_id), 2) AS diff
FROM employees;
